INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", 100101, "ヒヨリ", 44, "トゥインクルウィッシュ", 2, 27, "東山奈央", 155, "獣人族", 8, 16, "人助けが大好き！　前向き格闘娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 100201, "ユイ", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 100301, "レイ", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "いたずら、探検", 100401, "ミソギ", 27, "リトルリリカル", 5, 10, "諸星すみれ", 128, "ヒューマン", 8, 9, "探検好きのイタズラっ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "？？？", "ヒーローごっこ", 100501, "マツリ", 40, "王宮騎士団（NIGHTMARE）", 8, 25, "下田麻美", 146, "獣人族", 11, 12, "ヒーローに憧れる騎士見習いの少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "サックス", 100601, "アカリ", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "浅倉杏美", 150, "魔族", 11, 13, "甘え上手なみんなの人気者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリンを食べること", 100701, "ミヤコ", 32, "悪魔偽王国軍（ディアボロス）", 7, 23, "雨宮天", 130, "魔族", 1, 14, "プリン大好きゴースト娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "鏡で自分を見ること", 100801, "ユキ", 40, "ヴァイスフリューゲル　ランドソル支部", 15, 10, "大空直美", 150, "エルフ", 10, 14, "ボクは誰よりも美しい");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "小説執筆", 100901, "アンナ", 45, "トワイライトキャラバン", 13, 5, "髙野麻美", 159, "魔族", 7, 17, "前世を信じる中二病患者、「疾風の冥姫」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "空想、ぬいぐるみ集め", 101001, "マホ", 42, "自警団（カォン）", 10, 22, "内田真礼", 155, "獣人族", 9, 16, "マホマホ王国のプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "お裁縫", 101101, "リノ", 44, "ラビリンス", 3, 25, "阿澄佳奈", 156, "ヒューマン", 8, 15, "人懐っこくてマシンガントークな妹系少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "妹と遊ぶこと、二度寝、昼寝、早寝", 101201, "ハツネ", 46, "フォレスティエ", 6, 24, "大橋彩香", 156, "エルフ", 12, 17, "みんなのために超能力を使う眠り姫");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "読書、魔法", 101301, "ナナカ", 55, "トワイライトキャラバン", 13, 21, "佳村はるか", 166, "魔族", 8, 18, "オタク全開な魔法少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "test", "読書、推理", 101401, "カスミ", 41, "自警団（カォン）", 10, 3, "水瀬いのり", 152, "獣人族", 11, 15, "頭脳明晰な美少女名探偵");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "test", "絵本作り", 101501, "ミサト", 54, "フォレスティエ", 6, 5, "國府田マリ子", 165, "エルフ", 9, 21, "母性溢れる優しいみんなの「ミサト先生」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ファッション", 101601, "スズナ", 48, "ルーセント学院", 14, 10, "上坂すみれ", 167, "魔族", 4, 17, "天真爛漫で人気者のカリスマモデル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "踊り、空手", 101701, "カオリ", 53, "自警団（カォン）", 10, 7, "高森奈津美", 158, "獣人族", 7, 17, "いつでも「なんくるないさ～」な天然娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 101801, "イオ", 52, "ルーセント学院", 14, 14, "伊藤静", 162, "魔族", 8, 23, "多くの男性を魅了する無垢な女教師");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "かわいいもの集め", 102001, "ミミ", 21, "リトルリリカル", 5, 3, "日高里菜", 117, "獣人族", 4, 10, "お歌もにんじんも、ウサギさんも大好き♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "観劇、おままごと", 102101, "クルミ", 40, "サレンディア救護院", 9, 9, "植田佳奈", 150, "ヒューマン", 6, 12, "泣き虫で臆病な守ってあげたい女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "ゲーム全般", 102201, "ヨリ", 40, "悪魔偽王国軍（ディアボロス）", 7, 22, "原紗友里", 150, "魔族", 11, 13, "人見知りであまのじゃくな女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "屋内でできる遊び", 102301, "アヤネ", 38, "サレンディア救護院", 9, 10, "芹澤優", 148, "ヒューマン", 5, 14, "ぷうきちといつも一緒！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ご奉仕", 102501, "スズメ", 43, "サレンディア救護院", 9, 12, "悠木碧", 154, "ヒューマン", 12, 15, "お嬢さまのためにがんばるドジっ娘メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "test", "あんパン", 102601, "リン", 42, "牧場（エリザベスパーク）", 11, 1, "小岩井ことり", 144, "獣人族", 1, 17, "遊びと睡眠が何より大事なぐうたら娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "実験、裁縫、料理", 102701, "エリコ", 43, "トワイライトキャラバン", 13, 30, "橋本ちなみ", 154, "魔族", 7, 16, "運命の相手に一途すぎる乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", 102801, "サレン", 43, "サレンディア救護院", 9, 4, "堀江由衣", 156, "エルフ", 10, 17, "救護院を経営する優しい庶民派お嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "舞台鑑賞、ダンス", 102901, "ノゾミ", 40, "カルミナ", 4, 24, "日笠陽子", 157, "ヒューマン", 1, 17, "歌って踊れる大人気アイドル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "忍法開発", 103001, "ニノン", 51, "ヴァイスフリューゲル　ランドソル支部", 15, 31, "佐藤聡美", 163, "ヒューマン", 8, 16, "トーゴクの神秘、オシエテクダサイ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占い", 103101, "シノブ", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "大坪由佳", 157, "魔族", 12, 18, "占いが得意な霊能少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "慈善事業", 103201, "アキノ", 45, "メルクリウス財団", 12, 12, "松嵜麗", 157, "ヒューマン", 3, 18, "一人前の商人を目指すパワフルお嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "漫才", 103301, "マヒル", 35, "牧場（エリザベスパーク）", 11, 3, "新田恵海", 142, "ヒューマン", 3, 20, "みんなを笑顔にするお笑い牧場主");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ウインドーショッピング", 103401, "ユカリ", 55, "メルクリウス財団", 12, 16, "今井麻美", 164, "エルフ", 3, 22, "純情でほっとけない大人の女性");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "test", "お勉強", 103601, "キョウカ", 21, "リトルリリカル", 5, 2, "小倉唯", 118, "エルフ", 2, 8, "礼儀正しくしっかり者のちびっ子優等生");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "test", "剣術、年長者をからかう", 103701, "トモ", 43, "王宮騎士団（NIGHTMARE）", 8, 11, "茅原実里", 149, "ヒューマン", 8, 13, "義理堅くてからかい好きな剣術少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書、お散歩", 103801, "シオリ", 40, "牧場（エリザベスパーク）", 11, 3, "小清水亜美", 153, "獣人族", 11, 14, "読書が趣味の病弱少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "友達作りのイメトレ", 104001, "アオイ", 44, "フォレスティエ", 6, 6, "花澤香菜", 158, "エルフ", 6, 13, "「友達」に憧れる、エルフの森の女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "各種楽器", 104201, "チカ", 46, "カルミナ", 4, 3, "福原綾香", 163, "ヒューマン", 6, 17, "人々を守るために歌う、唱喚士の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "お菓子作り", 104301, "マコト", 54, "自警団（カォン）", 10, 9, "小松未可子", 168, "獣人族", 8, 17, "男勝りで情に厚いワイルド娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "test", "世界征服", 104401, "イリヤ", 50, "悪魔偽王国軍（ディアボロス）", 7, 5, "丹下桜", 172, "魔族", 5, "??", "かつては夜を支配した最強の吸血鬼");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "小説を読むこと", 104501, "クウカ", 49, "ヴァイスフリューゲル　ランドソル支部", 15, 19, "長妻樹里", 157, "ヒューマン", 11, 18, "妄想大好き！　ほんとは照れ屋な女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "猫とたわむれること", 104601, "タマキ", 48, "メルクリウス財団", 12, 1, "沼倉愛美", 158, "獣人族", 3, 19, "弱きを助け強きをくじく猫娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "？？？", "格闘技、湯浴み", 104701, "ジュン", 50, "王宮騎士団（NIGHTMARE）", 8, 25, "川澄綾子", 171, "ヒューマン", 10, 25, "素顔を見せない冷静沈着な女性騎士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "傭兵などのアルバイト", 104801, "ミフユ", 49, "メルクリウス財団", 12, 11, "田所あずさ", 163, "ヒューマン", 11, 20, "仕事も私事も効率優先な傭兵少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", 104901, "シズル", 54, "ラビリンス", 3, 24, "生天目仁美", 168, "ヒューマン", 10, 18, "お姉ちゃんがお世話してあげるからねっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ファッション誌鑑賞、コスメ集め", 105001, "ミサキ", 22, "ルーセント学院", 14, 3, "久野美咲", 120, "魔族", 1, 11, "ちょっとおませな恋に恋する女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "研究、実験", 105101, "ミツキ", 53, "トワイライトキャラバン", 13, 7, "三石琴乃", 166, "ヒューマン", 3, 27, "実験が趣味の危険な科学者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "毛繕い、お喋り", 105201, "リマ", 100, "牧場（エリザベスパーク）", 11, 14, "徳井青空", 150, "獣人族", 3, 17, "乙女チックなもふもふアニマル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "お菓子屋通い", 105301, "モニカ", 33, "ヴァイスフリューゲル　ランドソル支部", 15, 28, "辻あゆみ", 140, "ヒューマン", 7, 17, "見た目も中身もお子ちゃまな異国の軍人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "test", "裁縫", 105401, "ツムギ", 45, "カルミナ", 4, 7, "木戸衣吹", 153, "ヒューマン", 9, 14, "ファッション大好きなキュートガール");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "test", "観察", 105501, "アユミ", 43, "ヴァイスフリューゲル　ランドソル支部", 15, 7, "大関英里", 155, "エルフ", 4, 16, "どこまでも一途に慕う、純情乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "test", "釣り", 105601, "ルカ", 54, "トワイライトキャラバン", 13, 11, "佐藤利奈", 167, "ヒューマン", 7, 25, "人情味溢れる粋でいなせな「姉御」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "冒険、おしゃべり", 105701, "ジータ", 45, "？？？", "", 10, "金元寿子", 156, "ヒューマン", 3, 17, "空への冒険を夢見る騎空士の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", 105801, "ペコリーヌ", 46, "美食殿", 1, 31, "M・A・O", 156, "ヒューマン", 3, 17, "いつも元気な腹ペコ少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", 105901, "コッコロ", 35, "美食殿", 1, 11, "伊藤美来", 140, "エルフ", 5, 11, "主を慕う、小さなガイド役");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", 106001, "キャル", 39, "美食殿", 1, 2, "立花理香", 152, "獣人族", 9, 14, "行き倒れの謎のネコミミ魔法使い");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "冒険、思い出話", 106101, "ムイミ", 40, "？？？", "", 11, "潘めぐみ", 148, "ヒューマン", 8, 16, "さまよえる謎の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "キレイな葉っぱを集めること", 106301, "アリサ", 42, "？？？", "", 17, "優木かな", 155, "エルフ", 6, 15, "森番を目指すエルフの少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "読書、ストレッチ", 106401, "シェフィ", "???", "美食殿", 1, 14, "近藤玲奈", 147, "ドラゴン族", 12, 14, "記憶喪失のドラゴン娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "格闘技", 106501, "カヤ", "???", "ドラゴンズネスト", 17, 25, "小市眞琴", 156, "ドラゴン族", 6, 16, "拳で語る喧嘩屋ドラゴン少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "ゲーム", 106601, "イノリ", "???", "ドラゴンズネスト", 17, 29, "藤田茜", 145, "ドラゴン族", 9, 13, "口が達者なヘタレドラゴン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "絵画、読書", 106701, "ホマレ", "???", "ドラゴンズネスト", 17, 17, "大西沙織", 168, "ドラゴン族", 4, 25, "妖しい微笑で全てを見透かす臥竜の頭領");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "人間観察", 106801, "ラビリスタ", "??", "ラビリンス", 3, 25, "沢城みゆき", 160, "ヒューマン", 7, 25, "秘密結社ラビリンスの『迷宮女王』");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "占い、支配", 106901, "カイザーインサイト", "??", "？？？", "", 1, "蒼井翔太", 166, "獣人族", 7, 29, "謎に包まれたランドソルの主");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "物真似、芸術鑑賞", 107001, "ネネカ", "??", "？？？", "", 24, "井口裕香", 149, "エルフ", 3, 24, "研究所に隠れ住む物静かなお姉さん");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "強敵との闘争", 107101, "クリスティーナ", "??", "王宮騎士団（NIGHTMARE）", 8, 7, "たかはし智秋", 165, "ヒューマン", 2, 27, "傍若無人な王宮騎士団副団長");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", 107501, "ペコリーヌ（サマー）", 46, "美食殿", 1, 31, "M・A・O", 156, "ヒューマン", 3, 17, "いつも元気な腹ペコ少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", 107601, "コッコロ（サマー）", 35, "美食殿", 1, 11, "伊藤美来", 140, "エルフ", 5, 11, "主を慕う、小さなガイド役");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ご奉仕", 107701, "スズメ（サマー）", 43, "サレンディア救護院", 9, 12, "悠木碧", 154, "ヒューマン", 12, 15, "お嬢さまのためにがんばるドジっ娘メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", 107801, "キャル（サマー）", 39, "美食殿", 1, 2, "立花理香", 152, "獣人族", 9, 14, "行き倒れの謎のネコミミ魔法使い");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "猫とたわむれること", 107901, "タマキ（サマー）", 48, "メルクリウス財団", 12, 1, "沼倉愛美", 158, "獣人族", 3, 19, "弱きを助け強きをくじく猫娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "傭兵などのアルバイト", 108001, "ミフユ（サマー）", 49, "メルクリウス財団", 12, 11, "田所あずさ", 163, "ヒューマン", 11, 20, "仕事も私事も効率優先な傭兵少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占い", 108101, "シノブ（ハロウィン）", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "大坪由佳", 157, "魔族", 12, 18, "占いが得意な霊能少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリンを食べること", 108201, "ミヤコ（ハロウィン）", 32, "悪魔偽王国軍（ディアボロス）", 7, 23, "雨宮天", 130, "魔族", 1, 14, "プリン大好きゴースト娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ファッション誌鑑賞、コスメ集め", 108301, "ミサキ（ハロウィン）", 22, "ルーセント学院", 14, 3, "久野美咲", 120, "魔族", 1, 11, "ちょっとおませな恋に恋する女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "各種楽器", 108401, "チカ（クリスマス）", 46, "カルミナ", 4, 3, "福原綾香", 163, "ヒューマン", 6, 17, "人々を守るために歌う、唱喚士の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "観劇、おままごと", 108501, "クルミ（クリスマス）", 40, "サレンディア救護院", 9, 9, "植田佳奈", 150, "ヒューマン", 6, 12, "泣き虫で臆病な守ってあげたい女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "屋内でできる遊び", 108601, "アヤネ（クリスマス）", 38, "サレンディア救護院", 9, 10, "芹澤優", 148, "ヒューマン", 5, 14, "ぷうきちといつも一緒！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", 108701, "ヒヨリ（ニューイヤー）", 44, "トゥインクルウィッシュ", 2, 27, "東山奈央", 155, "獣人族", 8, 16, "人助けが大好き！　前向き格闘娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 108801, "ユイ（ニューイヤー）", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 108901, "レイ（ニューイヤー）", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "実験、裁縫、料理", 109001, "エリコ（バレンタイン）", 43, "トワイライトキャラバン", 13, 30, "橋本ちなみ", 154, "魔族", 7, 16, "運命の相手に一途すぎる乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", 109101, "シズル（バレンタイン）", 54, "ラビリンス", 3, 24, "生天目仁美", 168, "ヒューマン", 10, 18, "お姉ちゃんがお世話してあげるからねっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "読書", 109201, "アン", 55, "？？？", "", 1, "日笠陽子", 156, "ヒューマン", 12, 17, "英霊と契約を結んだマナリアの天才王女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "食べること、眠ること", 109301, "ルゥ", 45, "？？？", "", 4, "こやまきみこ", 144, "ヒューマン", 2, 16, "マナリア魔法学院の新入生");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "ピアノ", 109401, "グレア", 67, "？？？", "", 3, "福原綾香", 167, "半人半竜", 11, 17, "人を超越した力を有す心優しい竜姫");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "小説を読むこと", 109501, "クウカ（オーエド）", 49, "ヴァイスフリューゲル　ランドソル支部", 15, 19, "長妻樹里", 157, "ヒューマン", 11, 18, "妄想大好き！　ほんとは照れ屋な女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "忍法開発", 109601, "ニノン（オーエド）", 51, "ヴァイスフリューゲル　ランドソル支部", 15, 31, "佐藤聡美", 163, "ヒューマン", 8, 16, "トーゴクの神秘、オシエテクダサイ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "演劇鑑賞、詩文", 109701, "レム", "??", "？？？", "", 2, "水瀬いのり", 154, "鬼族", 2, 17, "鬼がかりの万能妹メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "読書", 109801, "ラム", "??", "？？？", "", 2, "村川梨衣", 154, "鬼族", 2, 17, "毒舌系鬼姉メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "パックの毛繕い、勉強", 109901, "エミリア", "??", "？？？", "", 23, "高橋李依", 164, "ハーフエルフ", 9, "??", "銀髪のおっとりハーフエルフ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ファッション", 110001, "スズナ（サマー）", 48, "ルーセント学院", 14, 10, "上坂すみれ", 167, "魔族", 4, 17, "天真爛漫で人気者のカリスマモデル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 110101, "イオ（サマー）", 52, "ルーセント学院", 14, 14, "伊藤静", 162, "魔族", 8, 23, "多くの男性を魅了する無垢な女教師");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "ファッション誌鑑賞、コスメ集め", 110201, "ミサキ（サマー）", 22, "ルーセント学院", 14, 3, "久野美咲", 120, "魔族", 1, 11, "ちょっとおませな恋に恋する女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", 110301, "サレン（サマー）", 43, "サレンディア救護院", 9, 4, "堀江由衣", 156, "エルフ", 10, 17, "救護院を経営する優しい庶民派お嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "お菓子作り", 110401, "マコト（サマー）", 54, "自警団（カォン）", 10, 9, "小松未可子", 168, "獣人族", 8, 17, "男勝りで情に厚いワイルド娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "踊り、空手", 110501, "カオリ（サマー）", 53, "自警団（カォン）", 10, 7, "高森奈津美", 158, "獣人族", 7, 17, "いつでも「なんくるないさ～」な天然娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "空想、ぬいぐるみ集め", 110601, "マホ（サマー）", 42, "自警団（カォン）", 10, 22, "内田真礼", 155, "獣人族", 9, 16, "マホマホ王国のプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "友達作りのイメトレ", 110701, "アオイ（編入生）", 44, "フォレスティエ", 6, 6, "花澤香菜", 158, "エルフ", 6, 13, "「友達」に憧れる、エルフの森の女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ダーツ", 110801, "クロエ", 42, "聖テレサ女学院（なかよし部）", 16, 7, "種﨑敦美", 154, "エルフ", 8, 17, "ダウンタウン育ちのダウナー系エルフ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ダンス、カラオケ", 110901, "チエル", 46, "聖テレサ女学院（なかよし部）", 16, 15, "佐倉綾音", 156, "ヒューマン", 9, 16, "自由奔放ナチュラル無礼な現代っ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "読書", 111001, "ユニ", 36, "聖テレサ女学院（なかよし部）", 16, 28, "小原好美", 142, "ヒューマン", 2, 18, "書庫に眠れる小さな賢人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "お勉強", 111101, "キョウカ（ハロウィン）", 21, "リトルリリカル", 5, 2, "小倉唯", 118, "エルフ", 2, 8, "礼儀正しくしっかり者のちびっ子優等生");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "いたずら、探検", 111201, "ミソギ（ハロウィン）", 27, "リトルリリカル", 5, 10, "諸星すみれ", 128, "ヒューマン", 8, 9, "探検好きのイタズラっ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "かわいいもの集め", 111301, "ミミ（ハロウィン）", 21, "リトルリリカル", 5, 3, "日高里菜", 117, "獣人族", 4, 10, "お歌もにんじんも、ウサギさんも大好き♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "「おともだち」を探すこと", 111401, "ルナ", 28, "？？？", "", 8, "小倉唯", 142, "ヒューマン", 1, "??", "おともだちを探す死霊術師の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "強敵との闘争", 111501, "クリスティーナ（クリスマス）", "??", "王宮騎士団（NIGHTMARE）", 8, 7, "たかはし智秋", 165, "ヒューマン", 2, 27, "傍若無人な王宮騎士団副団長");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "舞台鑑賞、ダンス", 111601, "ノゾミ（クリスマス）", 40, "カルミナ", 4, 24, "日笠陽子", 157, "ヒューマン", 1, 17, "歌って踊れる大人気アイドル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "世界征服", 111701, "イリヤ（クリスマス）", 50, "悪魔偽王国軍（ディアボロス）", 7, 5, "丹下桜", 172, "魔族", 5, "??", "かつては夜を支配した最強の吸血鬼");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", 111801, "ぺコリーヌ（ニューイヤー）", 46, "美食殿", 1, 31, "M・A・O", 156, "ヒューマン", 3, 17, "いつも元気な腹ペコ少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", 111901, "コッコロ（ニューイヤー）", 35, "美食殿", 1, 11, "伊藤美来", 140, "エルフ", 5, 11, "主を慕う、小さなガイド役");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", 112001, "キャル（ニューイヤー）", 39, "美食殿", 1, 2, "立花理香", 152, "獣人族", 9, 14, "行き倒れの謎のネコミミ魔法使い");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ご奉仕", 112101, "スズメ（ニューイヤー）", 43, "サレンディア救護院", 9, 12, "悠木碧", 154, "ヒューマン", 12, 15, "お嬢さまのためにがんばるドジっ娘メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "読書、推理", 112201, "カスミ（マジカル）", 41, "自警団（カォン）", 10, 3, "水瀬いのり", 152, "獣人族", 11, 15, "頭脳明晰な美少女名探偵");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書、お散歩", 112301, "シオリ（マジカル）", 40, "牧場（エリザベスパーク）", 11, 3, "小清水亜美", 153, "獣人族", 11, 14, "読書が趣味の病弱少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "友達と長話", 112401, "ウヅキ（デレマス）", 45, "ニュージェネレーションズ", 100, 24, "大橋彩香", 159, "ヒューマン", 4, 17, "弾ける笑顔！　アイドルを夢見る女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "犬の散歩", 112501, "リン（デレマス）", 44, "ニュージェネレーションズ", 100, 10, "福原綾香", 165, "ヒューマン", 8, 15, "クールビューティーな「蒼の剣士」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "ショッピング", 112601, "ミオ（デレマス）", 46, "ニュージェネレーションズ", 100, 1, "原紗友里", 161, "ヒューマン", 12, 15, "スーパースターを目指す元気娘☆☆★");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "あんパン", 112701, "リン（レンジャー）", 42, "牧場（エリザベスパーク）", 11, 1, "小岩井ことり", 144, "獣人族", 1, 17, "遊びと睡眠が何より大事なぐうたら娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "漫才", 112801, "マヒル（レンジャー）", 35, "牧場（エリザベスパーク）", 11, 3, "新田恵海", 142, "ヒューマン", 3, 20, "みんなを笑顔にするお笑い牧場主");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "お裁縫", 112901, "リノ（ワンダー）", 44, "ラビリンス", 3, 25, "阿澄佳奈", 156, "ヒューマン", 8, 15, "人懐っこくてマシンガントークな妹系少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "観察", 113001, "アユミ（ワンダー）", 43, "ヴァイスフリューゲル　ランドソル支部", 15, 7, "大関英里", 155, "エルフ", 4, 16, "どこまでも一途に慕う、純情乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "釣り", 113101, "ルカ（サマー）", 54, "トワイライトキャラバン", 13, 11, "佐藤利奈", 167, "ヒューマン", 7, 25, "人情味溢れる粋でいなせな「姉御」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "小説執筆", 113201, "アンナ（サマー）", 45, "トワイライトキャラバン", 13, 5, "髙野麻美", 159, "魔族", 7, 17, "前世を信じる中二病患者、「疾風の冥姫」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "読書、魔法", 113301, "ナナカ（サマー）", 55, "トワイライトキャラバン", 13, 21, "佳村はるか", 166, "魔族", 8, 18, "オタク全開な魔法少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "妹と遊ぶこと、二度寝、昼寝、早寝", 113401, "ハツネ（サマー）", 46, "フォレスティエ", 6, 24, "大橋彩香", 156, "エルフ", 12, 17, "みんなのために超能力を使う眠り姫");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "絵本作り", 113501, "ミサト（サマー）", 54, "フォレスティエ", 6, 5, "國府田マリ子", 165, "エルフ", 9, 21, "母性溢れる優しいみんなの「ミサト先生」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "格闘技、湯浴み", 113601, "ジュン（サマー）", 50, "王宮騎士団（NIGHTMARE）", 8, 25, "川澄綾子", 171, "ヒューマン", 10, 25, "素顔を見せない冷静沈着な女性騎士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "サックス", 113701, "アカリ（エンジェル）", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "浅倉杏美", 150, "魔族", 11, 13, "甘え上手なみんなの人気者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "ゲーム全般", 113801, "ヨリ（エンジェル）", 40, "悪魔偽王国軍（ディアボロス）", 7, 22, "原紗友里", 150, "魔族", 11, 13, "人見知りであまのじゃくな女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "裁縫", 113901, "ツムギ（ハロウィン）", 45, "カルミナ", 4, 7, "木戸衣吹", 153, "ヒューマン", 9, 14, "ファッション大好きなキュートガール");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 114001, "レイ（ハロウィン）", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ヒーローごっこ", 114101, "マツリ（ハロウィン）", 40, "王宮騎士団（NIGHTMARE）", 8, 25, "下田麻美", 146, "獣人族", 11, 12, "ヒーローに憧れる騎士見習いの少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "お菓子屋通い", 114201, "モニカ（マジカル）", 33, "ヴァイスフリューゲル　ランドソル支部", 15, 28, "辻あゆみ", 140, "ヒューマン", 7, 17, "見た目も中身もお子ちゃまな異国の軍人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "剣術、年長者をからかう", 114301, "トモ（マジカル）", 43, "王宮騎士団（NIGHTMARE）", 8, 11, "茅原実里", 149, "ヒューマン", 8, 13, "義理堅くてからかい好きな剣術少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "慈善事業", 114401, "アキノ（クリスマス）", 45, "メルクリウス財団", 12, 12, "松嵜麗", 157, "ヒューマン", 3, 18, "一人前の商人を目指すパワフルお嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", 114501, "サレン（クリスマス）", 43, "サレンディア救護院", 9, 4, "堀江由衣", 156, "エルフ", 10, 17, "救護院を経営する優しい庶民派お嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ウインドーショッピング", 114601, "ユカリ（クリスマス）", 55, "メルクリウス財団", 12, 16, "今井麻美", 164, "エルフ", 3, 22, "純情でほっとけない大人の女性");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "冒険、思い出話", 114701, "ムイミ（ニューイヤー）", 40, "？？？", "", 11, "潘めぐみ", 148, "ヒューマン", 8, 16, "さまよえる謎の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "物真似、芸術鑑賞", 115001, "ネネカ（ニューイヤー）", "??", "？？？", "", 24, "井口裕香", 149, "エルフ", 3, 24, "研究所に隠れ住む物静かなお姉さん");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", 115501, "コッコロ（儀装束）", 35, "美食殿", 1, 11, "伊藤美来", 140, "エルフ", 5, 11, "主を慕う、小さなガイド役");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 115601, "ユイ（儀装束）", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "読書、推理", 115701, "カスミ（サマー）", 41, "自警団（カォン）", 10, 3, "水瀬いのり", 152, "獣人族", 11, 15, "頭脳明晰な美少女名探偵");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "毛繕い、お喋り", 115801, "リマ（シンデレラ）", 100, "牧場（エリザベスパーク）", 11, 14, "徳井青空", 150, "獣人族", 3, 17, "乙女チックなもふもふアニマル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "お菓子作り", 115901, "マコト（シンデレラ）", 54, "自警団（カォン）", 10, 9, "小松未可子", 168, "獣人族", 8, 17, "男勝りで情に厚いワイルド娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "空想、ぬいぐるみ集め", 116001, "マホ（シンデレラ）", 42, "自警団（カォン）", 10, 22, "内田真礼", 155, "獣人族", 9, 16, "マホマホ王国のプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ダーツ", 116201, "クロエ（聖学祭）", 42, "聖テレサ女学院（なかよし部）", 16, 7, "種﨑敦美", 154, "エルフ", 8, 17, "ダウンタウン育ちのダウナー系エルフ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ダンス、カラオケ", 116301, "チエル（聖学祭）", 46, "聖テレサ女学院（なかよし部）", 16, 15, "佐倉綾音", 156, "ヒューマン", 9, 16, "自由奔放ナチュラル無礼な現代っ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "読書", 116401, "ユニ（聖学祭）", 36, "聖テレサ女学院（なかよし部）", 16, 28, "小原好美", 142, "ヒューマン", 2, 18, "書庫に眠れる小さな賢人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "ゲーム", 116501, "イノリ（タイムトラベル）", "???", "ドラゴンズネスト", 17, 29, "藤田茜", 145, "ドラゴン族", 9, 13, "口が達者なヘタレドラゴン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "格闘技", 116601, "カヤ（タイムトラベル）", "???", "ドラゴンズネスト", 17, 25, "小市眞琴", 156, "ドラゴン族", 6, 16, "拳で語る喧嘩屋ドラゴン少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "友達作りのイメトレ", 116701, "アオイ（作業服）", 44, "フォレスティエ", 6, 6, "花澤香菜", 158, "エルフ", 6, 13, "「友達」に憧れる、エルフの森の女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "猫とたわむれること", 116801, "タマキ（作業服）", 48, "メルクリウス財団", 12, 1, "沼倉愛美", 158, "獣人族", 3, 19, "弱きを助け強きをくじく猫娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "傭兵などのアルバイト", 116901, "ミフユ（作業服）", 49, "メルクリウス財団", 12, 11, "田所あずさ", 163, "ヒューマン", 11, 20, "仕事も私事も効率優先な傭兵少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "実験、裁縫、料理", 117001, "エリコ（サマー）", 43, "トワイライトキャラバン", 13, 30, "橋本ちなみ", 154, "魔族", 7, 16, "運命の相手に一途すぎる乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", 117101, "シズル（サマー）", 54, "ラビリンス", 3, 24, "生天目仁美", 168, "ヒューマン", 10, 18, "お姉ちゃんがお世話してあげるからねっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "舞台鑑賞、ダンス", 117201, "ノゾミ（サマー）", 40, "カルミナ", 4, 24, "日笠陽子", 157, "ヒューマン", 1, 17, "歌って踊れる大人気アイドル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "各種楽器", 117301, "チカ（サマー）", 46, "カルミナ", 4, 3, "福原綾香", 163, "ヒューマン", 6, 17, "人々を守るために歌う、唱喚士の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "裁縫", 117401, "ツムギ（サマー）", 45, "カルミナ", 4, 7, "木戸衣吹", 153, "ヒューマン", 9, 14, "ファッション大好きなキュートガール");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "研究、実験", 117501, "ミツキ（オーエド）", 53, "トワイライトキャラバン", 13, 7, "三石琴乃", 166, "ヒューマン", 3, 27, "実験が趣味の危険な科学者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "鏡で自分を見ること", 117601, "ユキ（オーエド）", 40, "ヴァイスフリューゲル　ランドソル支部", 15, 10, "大空直美", 150, "エルフ", 10, 14, "ボクは誰よりも美しい");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "踊り、空手", 117701, "カオリ（ハロウィン）", 53, "自警団（カォン）", 10, 7, "高森奈津美", 158, "獣人族", 7, 17, "いつでも「なんくるないさ～」な天然娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "忍法開発", 117801, "ニノン（ハロウィン）", 51, "ヴァイスフリューゲル　ランドソル支部", 15, 31, "佐藤聡美", 163, "ヒューマン", 8, 16, "トーゴクの神秘、オシエテクダサイ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ファッション", 117901, "スズナ（ハロウィン）", 48, "ルーセント学院", 14, 10, "上坂すみれ", 167, "魔族", 4, 17, "天真爛漫で人気者のカリスマモデル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "お金を数えること、悪だくみ", 118001, "クレジッタ", 57, "リッチモンド商工会", 18, 19, "Lynn", 160, "ヒューマン", 9, 26, "忠義に目覚めた女商人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "歌、読書、詩を書くこと", 118101, "ランファ", 53, "レイジ・レギオン", 19, 28, "原田彩楓", 165, "魔族", 12, 20, "静寂を求め歌う陰気少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "特に無し", 118201, "ミソラ", "??", "レイジ・レギオン", 19, 2, "鬼頭明里", 159, "ヒューマン", 7, 16, "明朗快活、なれど破滅に流るる溌溂少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "書類仕事、散歩、ボードゲーム", 118501, "カリン", 43, "？？？", "", 12, "洲崎綾", 152, "ヒューマン", 9, 24, "【ギルド管理協会】職員の親切なお姉さん");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "悪戯をすること", 118601, "ネビア", "???", "？？？", "", "?", "相坂優歌", "???", "？？？", "?", "??", "幻霧に戯れる悪戯好きなガイド妖精");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 119001, "イオ（ノワール）", 52, "ルーセント学院", 14, 14, "伊藤静", 162, "魔族", 8, 23, "多くの男性を魅了する無垢な女教師");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "小説を読むこと", 119101, "クウカ（ノワール）", 49, "ヴァイスフリューゲル　ランドソル支部", 15, 19, "長妻樹里", 157, "ヒューマン", 11, 18, "妄想大好き！　ほんとは照れ屋な女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "漫才", 119201, "マヒル（クリスマス）", 35, "牧場（エリザベスパーク）", 11, 3, "新田恵海", 142, "ヒューマン", 3, 20, "みんなを笑顔にするお笑い牧場主");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "お裁縫", 119301, "リノ（クリスマス）", 44, "ラビリンス", 3, 25, "阿澄佳奈", 156, "ヒューマン", 8, 15, "人懐っこくてマシンガントークな妹系少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリンを食べること", 119901, "ミヤコ（クリスマス）", 32, "悪魔偽王国軍（ディアボロス）", 7, 23, "雨宮天", 130, "魔族", 1, 14, "プリン大好きゴースト娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", 120001, "シズル（ノワール）", 54, "ラビリンス", 3, 24, "生天目仁美", 168, "ヒューマン", 10, 18, "お姉ちゃんがお世話してあげるからねっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "読書、ストレッチ", 120701, "シェフィ（ニューイヤー）", "???", "美食殿", 1, 14, "近藤玲奈", 147, "ドラゴン族", 12, 14, "記憶喪失のドラゴン娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "釣り", 120801, "ルカ（ニューイヤー）", 54, "トワイライトキャラバン", 13, 11, "佐藤利奈", 167, "ヒューマン", 7, 25, "人情味溢れる粋でいなせな「姉御」");
