INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "猫と遊ぶ", 121101, "キャル（オーバーロード）", 39, "美食殿", 1, 2, "立花理香", 152, "獣人族", 9, 14, "行き倒れの謎のネコミミ魔法使い");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "人間観察", 121201, "ラビリスタ（オーバーロード）", "??", "ラビリンス", 3, 25, "沢城みゆき", 160, "ヒューマン", 7, 25, "秘密結社ラビリンスの『迷宮女王』");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "観劇、おままごと", 121301, "クルミ（ステージ）", 40, "サレンディア救護院", 9, 9, "植田佳奈", 150, "ヒューマン", 6, 12, "泣き虫で臆病な守ってあげたい女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ファッション誌鑑賞、コスメ集め", 121401, "ミサキ（ステージ）", 22, "ルーセント学院", 14, 3, "久野美咲", 120, "魔族", 1, 11, "ちょっとおませな恋に恋する女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "観察", 121501, "アユミ（怪盗）", 43, "ヴァイスフリューゲル　ランドソル支部", 15, 7, "大関英里", 155, "エルフ", 4, 16, "どこまでも一途に慕う、純情乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "ゲーム", 121601, "イノリ（怪盗）", "???", "ドラゴンズネスト", 17, 29, "藤田茜", 145, "ドラゴン族", 9, 13, "口が達者なヘタレドラゴン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "小説執筆", 121901, "アンナ（パイレーツ）", 45, "トワイライトキャラバン", 13, 5, "髙野麻美", 159, "魔族", 7, 17, "前世を信じる中二病患者、「疾風の冥姫」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占い", 122001, "シノブ（パイレーツ）", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "大坪由佳", 157, "魔族", 12, 18, "占いが得意な霊能少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "友達作りのイメトレ", 122101, "アオイ（キャンプ）", 44, "フォレスティエ", 6, 6, "花澤香菜", 158, "エルフ", 6, 13, "「友達」に憧れる、エルフの森の女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ウインドーショッピング", 122201, "ユカリ（キャンプ）", 55, "メルクリウス財団", 12, 16, "今井麻美", 164, "エルフ", 3, 22, "純情でほっとけない大人の女性");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "お散歩、お料理", 122301, "ヴァンピィ", 41, "？？？", "", 6, "釘宮理恵", 149, "魔族", 12, "??", "けんぞくのご主人様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", 122401, "ヒヨリ（サマー）", 44, "トゥインクルウィッシュ", 2, 27, "東山奈央", 155, "獣人族", 8, 16, "人助けが大好き！　前向き格闘娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 122501, "レイ（サマー）", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 122601, "ユイ（サマー）", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "お勉強", 122701, "キョウカ（サマー）", 21, "リトルリリカル", 5, 2, "小倉唯", 118, "エルフ", 2, 8, "礼儀正しくしっかり者のちびっ子優等生");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "いたずら、探検", 122801, "ミソギ（サマー）", 27, "リトルリリカル", 5, 10, "諸星すみれ", 128, "ヒューマン", 8, 9, "探検好きのイタズラっ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "かわいいもの集め", 122901, "ミミ（サマー）", 21, "リトルリリカル", 5, 3, "日高里菜", 117, "獣人族", 4, 10, "お歌もにんじんも、ウサギさんも大好き♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "？？？", 123001, "アメス", "???", "？？？", "", "?", "相坂優歌", 150, "？？？", "?", "??", "新たな姿で騎士の冒険を支え続ける妖精");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "空想、ぬいぐるみ集め", 123101, "マホ（エクスプローラー）", 42, "自警団（カォン）", 10, 22, "内田真礼", 155, "獣人族", 9, 16, "マホマホ王国のプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "屋内でできる遊び", 123201, "アヤネ（エクスプローラー）", 38, "サレンディア救護院", 9, 10, "芹澤優", 148, "ヒューマン", 5, 14, "ぷうきちといつも一緒！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "可愛いショタと遊ぶ、買い物", 123301, "ネア", 55, "レイジ・レギオン", 19, 13, "和氣あず未", 157, "魔族？", 6, 19, "ショタ大好き♪　ギャル系スライム娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "格闘技、湯浴み", 123401, "ジュン（キャンプ）", 50, "王宮騎士団（NIGHTMARE）", 8, 25, "川澄綾子", 171, "ヒューマン", 10, 25, "素顔を見せない冷静沈着な女性騎士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "あんパン", 123501, "リン（ハロウィン）", 42, "牧場（エリザベスパーク）", 11, 1, "小岩井ことり", 144, "獣人族", 1, 17, "遊びと睡眠が何より大事なぐうたら娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "剣術、年長者をからかう", 123601, "トモ（ハロウィン）", 43, "王宮騎士団（NIGHTMARE）", 8, 11, "茅原実里", 149, "ヒューマン", 8, 13, "義理堅くてからかい好きな剣術少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "読書、魔法", 123701, "ナナカ（ハロウィン）", 55, "トワイライトキャラバン", 13, 21, "佳村はるか", 166, "魔族", 8, 18, "オタク全開な魔法少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "強敵との闘争", 123801, "クリスティーナ（ワイルド）", "??", "王宮騎士団（NIGHTMARE）", 8, 7, "たかはし智秋", 165, "ヒューマン", 2, 27, "傍若無人な王宮騎士団副団長");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "ヒーローごっこ", 123901, "マツリ（ワイルド）", 40, "王宮騎士団（NIGHTMARE）", 8, 25, "下田麻美", 146, "獣人族", 11, 12, "ヒーローに憧れる騎士見習いの少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "サックス", 124001, "アカリ（クリスマス）", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "浅倉杏美", 150, "魔族", 11, 13, "甘え上手なみんなの人気者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "ゲーム全般", 124101, "ヨリ（クリスマス）", 40, "悪魔偽王国軍（ディアボロス）", 7, 22, "原紗友里", 150, "魔族", 11, 13, "人見知りであまのじゃくな女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "格闘技、湯浴み", 124201, "ジュン（クリスマス）", 50, "王宮騎士団（NIGHTMARE）", 8, 25, "川澄綾子", 171, "ヒューマン", 10, 25, "素顔を見せない冷静沈着な女性騎士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "絵画、読書", 124501, "ホマレ（ニューイヤー）", "???", "ドラゴンズネスト", 17, 17, "大西沙織", 168, "ドラゴン族", 4, 25, "妖しい微笑で全てを見透かす臥竜の頭領");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "絵本作り", 124601, "ミサト（ニューイヤー）", 54, "フォレスティエ", 6, 5, "國府田マリ子", 165, "エルフ", 9, 21, "母性溢れる優しいみんなの「ミサト先生」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "研究、実験", 124701, "ミツキ（ニューイヤー）", 53, "トワイライトキャラバン", 13, 7, "三石琴乃", 166, "ヒューマン", 3, 27, "実験が趣味の危険な科学者");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "舞台鑑賞、ダンス", 124801, "ノゾミ（リベレイター）", 40, "カルミナ", 4, 24, "日笠陽子", 157, "ヒューマン", 1, 17, "歌って踊れる大人気アイドル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "格闘技", 124901, "カヤ（リベレイター）", "???", "ドラゴンズネスト", 17, 25, "小市眞琴", 156, "ドラゴン族", 6, 16, "拳で語る喧嘩屋ドラゴン少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "冒険、思い出話", 125001, "ムイミ（リベレイター）", 40, "？？？", "", 11, "潘めぐみ", 148, "ヒューマン", 8, 16, "さまよえる謎の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "猫とたわむれること", 125101, "タマキ（カフェ）", 48, "メルクリウス財団", 12, 1, "沼倉愛美", 158, "獣人族", 3, 19, "弱きを助け強きをくじく猫娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "お菓子屋通い", 125201, "モニカ（カフェ）", 33, "ヴァイスフリューゲル　ランドソル支部", 15, 28, "辻あゆみ", 140, "ヒューマン", 7, 17, "見た目も中身もお子ちゃまな異国の軍人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "瞑想、動植物の飼育", 125301, "コッコロ（レンジャー）", 35, "美食殿", 1, 11, "伊藤美来", 140, "エルフ", 5, 11, "主を慕う、小さなガイド役");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書、お散歩", 125401, "シオリ（レンジャー）", 40, "牧場（エリザベスパーク）", 11, 3, "小清水亜美", 153, "獣人族", 11, 14, "読書が趣味の病弱少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "冒険、おしゃべり", 125501, "ジータ（ウォーロック）", 45, "？？？", "", 10, "金元寿子", 156, "ヒューマン", 3, 17, "空への冒険を夢見る騎空士の少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "ネズ耳作り", 125601, "ビカラ", 39, "？？？", "", 4, "種﨑敦美", 145, "ヒューマン", 12, 14, "陰陽合わせ持つ鼠神宮の巫女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "書類仕事、散歩、ボードゲーム", 125701, "カリン（アルケミスト）", 43, "？？？", "", 12, "洲崎綾", 152, "ヒューマン", 9, 24, "【ギルド管理協会】職員の親切なお姉さん");
