INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "世界征服", 126201, "イリヤ（儀装束）", 50, "悪魔偽王国軍（ディアボロス）", 7, 5, "丹下桜", 172, "魔族", 5, "??", "かつては夜を支配した最強の吸血鬼");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "鏡で自分を見ること", 126301, "ユキ（儀装束）", 40, "ヴァイスフリューゲル　ランドソル支部", 15, 10, "大空直美", 150, "エルフ", 10, 14, "ボクは誰よりも美しい");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "昼寝、誰かの役に立つこと", 126401, "クローチェ", "全重量252", "？？？", "", 11, "長谷川育美", 170, "機械人族", 11, "??", "スマイル満タン！　パワフル機械少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "昼寝、新作スイーツの試食", 126501, "ライラエル", "??", "？？？", "", 17, "河瀬茉希", 162, "天使族", 1, "??", "優しさと傲慢さを併せ持つプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "物真似、芸術鑑賞", 126601, "ネネカ（サマー）", "??", "？？？", "", 24, "井口裕香", 149, "エルフ", 3, 24, "研究所に隠れ住む物静かなお姉さん");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "慈善事業", 126701, "アキノ（サマー）", 45, "メルクリウス財団", 12, 12, "松嵜麗", 157, "ヒューマン", 3, 18, "一人前の商人を目指すパワフルお嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ウインドーショッピング", 126801, "ユカリ（サマー）", 55, "メルクリウス財団", 12, 16, "今井麻美", 164, "エルフ", 3, 22, "純情でほっとけない大人の女性");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "", "歌、読書、詩を書くこと", 126901, "ランファ（サマー）", 53, "レイジ・レギオン", 19, 28, "原田彩楓", 165, "魔族", 12, 20, "静寂を求め歌う陰気少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "小説を読むこと", 127001, "クウカ（サマー）", 49, "ヴァイスフリューゲル　ランドソル支部", 15, 19, "長妻樹里", 157, "ヒューマン", 11, 18, "妄想大好き！　ほんとは照れ屋な女の子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占い", 127101, "シノブ（サマー）", 42, "悪魔偽王国軍（ディアボロス）", 7, 22, "大坪由佳", 157, "魔族", 12, 18, "占いが得意な霊能少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "猫と遊ぶ", 127201, "キャル（編入生）", 39, "美食殿", 1, 2, "立花理香", 152, "獣人族", 9, 14, "行き倒れの謎のネコミミ魔法使い");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ファッション", 127301, "スズナ（編入生）", 48, "ルーセント学院", 14, 10, "上坂すみれ", 167, "魔族", 4, 17, "天真爛漫で人気者のカリスマモデル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "経営、お茶会", 127501, "サレン（サラサリア）", 43, "サレンディア救護院", 9, 4, "堀江由衣", 156, "エルフ", 10, 17, "救護院を経営する優しい庶民派お嬢様");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "釣り", 127601, "ルカ（サラサリア）", 54, "トワイライトキャラバン", 13, 11, "佐藤利奈", 167, "ヒューマン", 7, 25, "人情味溢れる粋でいなせな「姉御」");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "妹と過ごす休日", 127701, "リンド", "???", "？？？", "", 5, "豊田萌絵", 145, "ドラゴン族", 2, 12, "真面目で一生懸命なドラゴンメイド（姉）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "?", "", "サボり、姉と過ごす休日", 127801, "ヴルム", "???", "？？？", "", 5, "関根明良", 145, "ドラゴン族", 2, 12, "不真面目で気怠げなドラゴンメイド（妹）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "食べ歩き、料理", 127901, "ペコリーヌ（クリスマス）", 46, "美食殿", 1, 31, "M・A・O", 156, "ヒューマン", 3, 17, "いつも元気な腹ペコ少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "お金を数えること、悪だくみ", 128001, "クレジッタ（クリスマス）", 57, "リッチモンド商工会", 18, 19, "Lynn", 160, "ヒューマン", 9, 26, "忠義に目覚めた女商人");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "ゲーム", 128301, "イノリ（ニューイヤー）", "???", "ドラゴンズネスト", 17, 29, "藤田茜", 145, "ドラゴン族", 9, 13, "口が達者なヘタレドラゴン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "妹と遊ぶこと、二度寝、昼寝、早寝", 128401, "ハツネ（ニューイヤー）", 46, "フォレスティエ", 6, 24, "大橋彩香", 156, "エルフ", 12, 17, "みんなのために超能力を使う眠り姫");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "AB", "", "読書、推理", 128501, "カスミ（ニューイヤー）", 41, "自警団（カォン）", 10, 3, "水瀬いのり", 152, "獣人族", 11, 15, "頭脳明晰な美少女名探偵");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助け、応援", 128701, "ヒヨリ（アストラル）", 44, "トゥインクルウィッシュ", 2, 27, "東山奈央", 155, "獣人族", 8, 16, "人助けが大好き！　前向き格闘娘");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 128801, "レイ（アストラル）", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 128901, "ユイ（アストラル）", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
