INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "実験、裁縫、料理", 129901, "エリコ（コマンダー）", 43, "トワイライトキャラバン", 13, 30, "橋本ちなみ", 154, "魔族", 7, 16, "運命の相手に一途すぎる乙女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "妹たちを躾ける", 130001, "ヤマト", 55, "バンディ・シスターズ", 21, 8, "ファイルーズあい", 168, "エルフ", 1, 21, "悪運に愛された、盗賊ギルドの頭領長女");
