INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ご奉仕", 130801, "スズメ（スプリング）", 43, "サレンディア救護院", 9, 12, "悠木碧", 154, "ヒューマン", 12, 15, "お嬢さまのためにがんばるドジっ娘メイド");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "掃除、宝石や遊園地の手入れ", 130901, "クルル", 46, "ジオ・テオゴニア", "", 2, "田中美海", 158, "宝石兎族", 8, 16, "なんでもあげちゃうポンコツ支配人バニー");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "空想、ぬいぐるみ集め", 131001, "マホ（ドリームパーク）", 42, "自警団（カォン）", 10, 22, "内田真礼", 155, "獣人族", 9, 16, "マホマホ王国のプリンセス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "", "可愛いショタと遊ぶ、買い物", 131101, "ネア（サマー）", 55, "レイジ・レギオン", 19, 13, "和氣あず未", 157, "魔族？", 6, 19, "ショタ大好き♪　ギャル系スライム娘");
