INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "A", "", "特に無し", 136301, "ミソラ（クリスマス）", "??", "レイジ・レギオン", 19, 2, "鬼頭明里", 159, "ヒューマン", 7, 16, "明朗快活、なれど破滅に流るる溌溂少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "料理、人間観察", 136401, "ユイ（クリスマス）", 47, "トゥインクルウィッシュ", 2, 5, "種田梨沙", 158, "ヒューマン", 4, 17, "戦闘のサポートが得意な、心優しい少女");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "家事全般", 136501, "シズル（ニューイヤー）", 54, "ラビリンス", 3, 24, "生天目仁美", 168, "ヒューマン", 10, 18, "お姉ちゃんがお世話してあげるからねっ！");
