INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "忍法開発", 137101, "ニノン（サマー）", 51, "ヴァイスフリューゲル　ランドソル支部", 15, 31, "佐藤聡美", 163, "ヒューマン", 8, 16, "トーゴクの神秘、オシエテクダサイ！");
