INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "読書、乗馬、お茶", 180301, "レイ（プリンセス）", 46, "トゥインクルウィッシュ", 2, 12, "早見沙織", 163, "魔族", 1, 18, "クールで何事にも真っ直ぐな剣士");
